{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "Under the disability path, the student would need one of the listed disabilities, an active individualized education program (IEP) naming one of those disabilities as a primary or secondary disability when the department receives the request",
      "rationale": "Conveys the disability and active-IEP requirements and timing, but never identifies the qualifying disabilities or their state-board-defined scope."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "either a full year of attendance at a Tennessee public school immediately before receiving an IEA, first-time enrollment in a Tennessee school, or an IEA in the previous school year",
      "rationale": "Conveys all three alternative enrollment/history requirements for the disability path."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "A Tennessee resident could qualify through one of two paths. Under the disability path, the student would need one of the listed disabilities, an active individualized education program (IEP) naming one of those disabilities as a primary or secondary disability when the department receives the request, and either a full year of attendance at a Tennessee public school immediately before receiving an IEA, first-time enrollment in a Tennessee school, or an IEA in the previous school year. Under the other path, the student would need a medical condition that the state board of education determines prevents in-person school attendance and must be entitled to attend a public school.",
      "rationale": "Conveys residency, a separate medical-condition route, the board's determination, and public-school entitlement. However, 'prevents' narrows the bill's condition that the medical condition 'inhibits' in-person attendance."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "For a student qualifying through the medical-condition path, a home school could be a participating school.",
      "rationale": "Conveys home-school participation for medical-route students, but omits the definition's nonpublic-school branch and its requirements to meet Part 14 standards and seek to enroll eligible students."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Those students and home schools would be exempt from the requirements in § 49-10-1404; the bill does not show those requirements.",
      "rationale": "Correctly identifies the exempt medical-route students and participating home schools and the section made inapplicable."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "The bill would also specify that references to participating schools in two other provisions refer to nonpublic participating schools.",
      "rationale": "Conveys the narrowing to nonpublic schools but does not identify § 49-10-1403(d) and § 49-10-1405(a)(7). Those citations are necessary to identify the affected provisions because their substantive contents are not supplied."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "A parent of a student qualifying through the medical-condition path would have to use IEA funds only for the approved expenses listed in § 49-10-1403(b).",
      "rationale": "Conveys the parent's obligation, the medical-route scope, and the limitation to the specified approved expenses."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "The department would have to regularly monitor those funds for compliance.",
      "rationale": "Conveys mandatory regular monitoring of medical-route funds, but omits the express requirement to create and implement a monitoring process."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "It could suspend or terminate a student's participation if the parent fails to comply.",
      "rationale": "In context, conveys the department's discretionary suspension or termination authority for parental noncompliance with the new requirements."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "A student whose participation is terminated on that basis could not participate again.",
      "rationale": "Conveys permanent future ineligibility following termination for the specified noncompliance."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "It would take effect July 1, 2026.",
      "rationale": "States the effective date correctly."
    }
  ]
}
